"use client";

import type { ReactNode } from "react";

import { mixOklch, useFramecnTheme } from "@/lib/framecn-ui";
import type { FramecnTheme } from "@/lib/framecn-ui";
import { SkeletonBlock } from "@/components/framecn/skeleton-block";

export type SkeletonState = "loading" | "loaded";

export type SkeletonLayout = "lines" | "card";

export interface SkeletonProps {
  state?: SkeletonState;
  style?: SkeletonStyle;
  children?: ReactNode;
  placeholder?: ReactNode;
  layout?: SkeletonLayout;
  speed?: number;
  theme?: Partial<FramecnTheme>;
  className?: string;
}

export interface SkeletonStyle {
  skeletonOpacity: number;
  contentOpacity: number;
}

export const skeletonStyle = (state: SkeletonState): SkeletonStyle => {
  switch (state) {
    case "loaded": {
      return { contentOpacity: 1, skeletonOpacity: 0 };
    }
    default: {
      return { contentOpacity: 0, skeletonOpacity: 1 };
    }
  }
};

const LayoutPlaceholder = ({
  layout,
  speed,
  theme,
}: {
  layout: SkeletonLayout;
  speed?: number;
  theme: FramecnTheme;
}) => {
  const shimmer = {
    baseColor: theme.accent,
    highlightColor: mixOklch(theme.accent, theme.foreground, 0.13),
    radius: Math.max(0, theme.radius - 2),
    speed,
  };
  if (layout === "card") {
    return (
      <div style={{ alignItems: "center", display: "flex", gap: 14 }}>
        <SkeletonBlock
          width={48}
          height={48}
          flexShrink={0}
          {...shimmer}
          radius={24}
        />
        <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
          <SkeletonBlock width={180} height={14} {...shimmer} />
          <SkeletonBlock width={120} height={14} {...shimmer} />
        </div>
      </div>
    );
  }
  return (
    <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
      <SkeletonBlock width={260} height={14} {...shimmer} />
      <SkeletonBlock width={240} height={14} {...shimmer} />
      <SkeletonBlock width={160} height={14} {...shimmer} />
    </div>
  );
};

export const Skeleton = ({
  state = "loading",
  style,
  children,
  placeholder,
  layout = "lines",
  speed,
  theme: themeOverride,
  className,
}: SkeletonProps) => {
  const theme = useFramecnTheme(themeOverride);
  const v = style ?? skeletonStyle(state);
  const placeholderLayer = placeholder ?? (
    <LayoutPlaceholder layout={layout} speed={speed} theme={theme} />
  );
  return (
    <div
      className={className}
      style={{
        display: "inline-block",
        fontFamily:
          "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
        position: "relative",
      }}
    >
      <div style={{ opacity: v.contentOpacity }}>{children}</div>

      <div
        style={{
          inset: 0,
          opacity: v.skeletonOpacity,
          pointerEvents: "none",
          position: "absolute",
        }}
      >
        {placeholderLayer}
      </div>
    </div>
  );
};

"use client";

import { easings, useStateTransition } from "@/lib/framecn-ui";
import type { Step } from "@/lib/framecn-ui";
import { skeletonStyle } from "@/components/framecn/skeleton";
import type {
  SkeletonState,
  SkeletonStyle,
} from "@/components/framecn/skeleton";

export const DEFAULT_DURATION = 12;

export const tweenSkeletonStyle = (
  a: SkeletonStyle,
  b: SkeletonStyle,
  t: number
): SkeletonStyle => ({
  contentOpacity: a.contentOpacity + (b.contentOpacity - a.contentOpacity) * t,
  skeletonOpacity:
    a.skeletonOpacity + (b.skeletonOpacity - a.skeletonOpacity) * t,
});

export interface SkeletonTransitionOptions {
  mode?: "light" | "dark";
  speed?: number;
  defaultDuration?: number;
}

export const useSkeletonTransition = (
  steps: Step<SkeletonState>[],
  opts: SkeletonTransitionOptions = {}
): SkeletonStyle => {
  const { speed = 1, defaultDuration = DEFAULT_DURATION } = opts;
  const { from, to, progress } = useStateTransition(
    steps,
    "loading",
    speed,
    defaultDuration
  );
  const t = easings.out(progress);
  return tweenSkeletonStyle(skeletonStyle(from), skeletonStyle(to), t);
};
